// Nhan dien 6 truong hop thay doi + xac dinh COT Postgres tuong ung de ghi de (neu co).
// Tra ve NHIEU item (1 item = 1 thay doi), khong can node Split Out rieng.
const body = $('ClickUp Trigger (Live)').first().json;
const historyItems = body.history_items || [];
const taskId = body.task_id;

// Dong bo voi fieldNameMap ben SQL_ClickUp_Full_Reconcile.json - CAP NHAT CA 2 CHO neu doi field
const CUSTOM_FIELD_TO_COLUMN = {
  "B1 Datum": "b1_datum", "DOB": "dob", "Mã HĐ": "ma_hd", "Nghề": "nghe", "SDT": "sdt",
  "email": "email", "Địa chỉ VN": "dia_chi_vn", "🌍 VFS": "vfs",
  "📆 Dự kiến thời gian đến Đức": "du_kien_den_duc", "🛫 Ngày xuất cảnh": "ngay_xuat_canh",
  "DKPV 2026": "dkpv_2026", "PVTC 2026": "pvtc_2026", "Nhà cửa / Support": "nha_cua_support",
  "Phụ trách": "phu_trach", "DKPV": "dkpv", "PVTC": "pvtc", "VFS": "vfs_khong_dau",
  "Plan bay": "planbay", "Ngày bay": "ngaybay", "Color": "color", "Link khác": "other_link",
};

function extractPlainTextFromDelta(raw) {
  try {
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (parsed && Array.isArray(parsed.ops)) {
      return parsed.ops.map(op => (typeof op.insert === 'string' ? op.insert : '')).join('').trim();
    }
  } catch (e) { }
  return typeof raw === 'string' ? raw : '';
}

const results = [];
for (const h of historyItems) {
  const changedBy = h.user?.username || 'không rõ';
  const dateStr = h.date ? new Date(Number(h.date)).toLocaleString('vi-VN') : '';
  let column = null, label = null, displayValue = null, dbValue = null;

  if (h.field === 'comment' && h.comment) {
    // Trich link OneDrive/Youtube ngay trong payload webhook (khong can goi lai API):
    // doc ca mang comment[].attributes.link/bookmark.url (hyperlink co anchor text khac URL)
    // LAN regex tren text_content (link dan tho) lam fallback.
    const URL_RE = /https?:\/\/[^\s)"'\]]+/g;
    function classifyLink(url) {
      const u = url.toLowerCase();
      if (u.includes('onedrive.live.com') || u.includes('1drv.ms') || u.includes('sharepoint.com')) return 'onedrive';
      if (u.includes('youtube.com') || u.includes('youtu.be')) return 'youtube';
      return null;
    }
    let foundLink = null, kind = null;
    const segs = Array.isArray(h.comment.comment) ? h.comment.comment : [];
    for (const seg of segs) {
      const candidate = seg.bookmark?.url || seg.attributes?.link;
      if (candidate) { const k = classifyLink(candidate); if (k) { foundLink = candidate; kind = k; break; } }
    }
    if (!foundLink) {
      const plain = h.comment.text_content || '';
      for (const url of (plain.match(URL_RE) || [])) {
        const k = classifyLink(url); if (k) { foundLink = url; kind = k; break; }
      }
    }
    if (foundLink && kind === 'onedrive') {
      column = 'onedrive_link'; label = 'OneDrive'; dbValue = foundLink; displayValue = foundLink;
    } else if (foundLink && kind === 'youtube') {
      column = 'youtube_link'; label = 'Youtube'; dbValue = foundLink; displayValue = foundLink;
    } else {
      label = 'Comment mới'; displayValue = 'Có comment mới trên task (không phải link OneDrive/Youtube)';
    }
  } else if (h.field === 'content') {
    column = 'description'; label = 'Mô tả';
    const text = extractPlainTextFromDelta(h.after);
    dbValue = text; displayValue = text.length > 200 ? text.slice(0, 200) + '…' : (text || '(trống)');
  } else if (h.field === 'custom_field' && h.custom_field) {
    const cfName = h.custom_field.name;
    column = CUSTOM_FIELD_TO_COLUMN[cfName] || null; // chi ghi DB neu field nam trong danh sach da biet
    label = cfName;
    dbValue = (h.after && typeof h.after === 'object') ? JSON.stringify(h.after) : (h.after ?? '');
    displayValue = (dbValue === '' || dbValue === null || dbValue === undefined) ? '(trống)' : dbValue;
  } else if (h.field === 'assignee_add') {
    column = 'phu_trach'; label = 'Phụ trách (thêm)';
    dbValue = h.after?.username || h.after?.email || '';
    displayValue = dbValue || 'không rõ';
  } else if (h.field === 'name') {
    column = 'name'; label = 'Tên task';
    dbValue = h.after; displayValue = h.after;
  } else if (h.field === 'status') {
    column = 'status'; label = 'Trạng thái';
    const before = (h.before && typeof h.before === 'object') ? h.before.status : h.before;
    const after = (h.after && typeof h.after === 'object') ? h.after.status : h.after;
    dbValue = after;
    displayValue = `${before || '—'} ➜ ${after || '—'}`;
  } else {
    continue; // field khong theo doi (due_date, priority, assignee_rem...) - bo qua
  }

  results.push({ json: { taskId, column, label, displayValue, dbValue, changedBy, dateStr } });
}

if (results.length === 0) {
  return [{ json: { taskId, skip: true } }];
}
return results;

const change = $('Nhận Diện & Format Thay Đổi').item.json;
const admin = $('⚙️ Config (Admin Chat ID)').first().json;
const task = $json; // { id, name, url } - tu Ghi De Postgres (RETURNING) hoac Lay Thong Tin Task (SELECT)

const text = `🔄 <b>Thông báo CẬP NHẬT Task</b>\n\n` +
  `🔧 Thay đổi:\n` +
  `📝 Trường "${change.label}" được cập nhật bởi ${change.changedBy}\n` +
  `✅ Giá trị mới: ${change.displayValue}\n\n` +
  `📦 Thông tin:\n` +
  `🆔 ID: ${task.id || change.taskId}\n` +
  `📌 Tên: ${task.name || '—'}\n` +
  `🔗 Link: ${task.url || '—'}\n` +
  (change.dateStr ? `🕒 Cập nhật lúc: ${change.dateStr}\n` : '') +
  `#task_updated`;

return [{ json: { chatId: admin.adminChatId, text } }];

// Dien tay Chat ID admin - KHONG con doc tu Postgres nua theo yeu cau.
// DOI GIA TRI nay neu can gui sang chat/group Telegram khac.
const ADMIN_CHAT_ID = "975005174";

return [{ json: { ...$json, adminChatId: ADMIN_CHAT_ID } }];
